import type { MetadataRoute } from "next";
/* Relative, with the extension, so the SEO tests can read the manifest itself. */
import { RYNTRA_COLORS } from "./brand/mark.ts";
import { HOMEPAGE_COPY } from "../lib/site/homepage-copy.ts";

/**
 * The web app manifest — the home-screen icons of the brand book v1.0. The
 * icons are the brand's dark tile, generated by scripts/render-brand-assets.mjs;
 * the colours are the dark ground so an installed shell never flashes white.
 *
 * The description is the product's line of 2026-09-26, from the same source as
 * the title and the share card. An installed app opens Home itself — the app,
 * not the site's front door, which is a redirect today and a landing again
 * later.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Ryntra",
    short_name: "Ryntra",
    description: HOMEPAGE_COPY.en.tagline,
    start_url: "/app/home",
    /* The whole site stays in the installed app's scope, as it was when it started at `/`. */
    scope: "/",
    display: "standalone",
    background_color: RYNTRA_COLORS.graphite,
    theme_color: RYNTRA_COLORS.graphite,
    icons: [
      { src: "/brand/icon-192.png", sizes: "192x192", type: "image/png" },
      { src: "/brand/icon-512.png", sizes: "512x512", type: "image/png" },
      { src: "/brand/icon-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
